def is_touching(a: ImagePatch, b: ImagePatch, margin: float = 0.0) -> bool:
    return abs(a.horizontal_center - b.horizontal_center) < margin and abs(a.vertical_center - b.vertical_center) < margin

def is_watching(watcher: ImagePatch, subject: ImagePatch, target: ImagePatch, margin: float = 0.0) -> bool:
    return is_in_front_of(watcher, subject, margin) and is_in_front_of(subject, target, margin)

